  match(3, "自然キーと人工キー", [53], "例をキーの種類と対応させなさい。", [["業務上もともと使う学籍番号", "自然キー"], ["識別のためにDB側で新設した連番", "人工キー"]], [], "自然キーを必ず人工キーへ置き換えるという意味ではありません。講義では論理設計は自然キーを基本として進めます。");
  single(3, "外部キーの置き場所", [54], "1教員が複数科目を担当し、1科目には担当教員が1人いる。教授professorsと科目coursesの外部キーの置き方を選びなさい。", "courses.professor_idからprofessors.idを参照する", ["professors.course_idだけで全ての担当科目を表す", "常に両方に相手の主キーを1列ずつ持たせる", "1対多でも必ず関連専用の中間テーブルを作る"], "多側の科目に1側の教員を参照するキーを置けば、教員に属する科目を何件でも管理できます。");
  single(3, "多対多のエンティティ化", [59, 60, 61, 62, 63], "ゴルフの参加を『多対多の関連』として扱う設計と、『スコアカードという実体』として扱う設計について、資料の説明に合うものを選びなさい。", "ER図が異なっても、同じ構造の関係スキーマに対応することがある", ["実体として扱うと必ず主キーが不要になる", "関連に属性を持たせることは絶対にできない", "多対多の関連からテーブルを作ることはできない"], "関連を中間テーブルにする場合と、関連を実体化してテーブルにする場合とで、同じ構造になる例が示されています。");
  match(3, "CDスキーマのキー", [66, 67, 71], "1枚のCD内でトラック番号が一意、1アーティストの参加記録は1トラックに1件とする。主キーを対応させなさい。", [["cds", "id"], ["tracks", "cd_idとtrack_number"], ["play", "cd_idとtrack_numberとartist_id"]], ["music_idだけ"], "トラック番号は別のCDでも使われます。演奏参加は同じトラックの複数アーティストを区別する必要があります。");
  single(3, "複合外部キーのSQL", [71], "playの(cd_id,track_number)からtracksの同名の複合主キーを参照する正しい指定を選びなさい。", "FOREIGN KEY (cd_id, track_number) REFERENCES tracks(cd_id, track_number)", ["FOREIGN KEY (cd_id) REFERENCES tracks(track_number)", "PRIMARY KEY (artist_id) REFERENCES tracks(cd_id)", "FOREIGN KEY (cd_id, artist_id) REFERENCES tracks(cd_id, track_number)"], "2つの列を1組として参照します。片方だけを別々に参照しても、存在するトラックの組を特定できません。");
  single(3, "自己参照外部キー", [66, 71], "artists.member_idからartists.idを参照する定義は何を表せるか。", "アーティスト個人から、その所属グループのアーティスト記録を参照する", ["必ず別のデータベースのレコードを参照する", "外部キーなので同じ表を参照することは不可能", "全アーティストの名前を自動的に同じ文字列にする"], "外部キーは自己参照も可能です。個人とグループを同じartistsの異なるレコードで管理できます。");
  multi(3, "キー制約", [70, 71, 72], "自動採番を行わない主キー列にNOT NULLを指定し、外部キー制約を有効にする。参照先削除時の特別なCASCADE等は設定しない。エラーとなる操作を全て答えなさい。", ["同じ主キー値を持つ行を追加する", "NOT NULLの主キー列にNULLを明示的に入れる", "参照先に存在しない値を外部キーへ設定する", "参照されている親レコードを削除する"], ["複数の子レコードが同じ親の主キー値を参照する"], "外部キーは一意でなくてもよいため、複数の社員が同じ部署を参照できます。ここではINTEGER PRIMARY KEYの自動採番などの例外を除き、明示された制約を考えます。");
  single(3, "SQLiteの参照整合性", [72], "SQLiteで資料の外部キー制約を有効にする指定を選びなさい。", "PRAGMA foreign_keys=true;", ["PRAGMA primary_key=false;", "DROP FOREIGN KEY;", "SELECT foreign_keys FROM all;"], "資料では外部キー制約が既定で無効であることに注意しています。ONを指定する書き方も同じ意味です。");
  single(3, "挿入の順序", [77, 78], "外部キー制約を有効にして親子レコードを登録する。安全な基本順序を選びなさい。", "参照される親レコードを先に登録し、その後に子レコードを登録する", ["必ず子から登録し、親は後回しにする", "参照先が未登録でも常に自動で親が作られる", "キーを設定すればINSERTは不要になる"], "存在しない親のキーを参照すると外部キー制約に抵触します。循環参照などは別途設計が必要ですが、今回の基本例は親から登録します。");
  single(3, "出力名と並べ替え", [28, 29], "SELECT s.out+s.in AS gross ... ORDER BY c.id; におけるASとORDER BYの役割の正しい組を選びなさい。", "ASは出力列の別名、ORDER BYは出力行の並べ替えを指定する", ["ASは条件選択、ORDER BYは重複削除", "ASは外部キー、ORDER BYは主キー", "どちらもテーブルを削除する"], "計算式の出力列にgrossという名前を付け、大会IDの順に結果を整列できます。");
  single(3, "ER図の使い分け", [72], "講義で説明された概念設計用ER図と、テーブル定義から自動生成した詳細ER図の使い分けを選びなさい。", "全体の実体・関連を考える図と、カラム・キーを確認する詳細図を目的に応じて使い分ける", ["自動生成図さえあれば最初の要件整理は不要", "両者は必ず同じ記法でなければならない", "カギマークは全て外部キーだけを示す"], "自動生成した詳細図はテーブル・列・主キー・外部キーの確認に便利ですが、概念段階の全体像には実体と関連を整理する図が適しています。");

  match(4, "直接・間接実行と出力", [17, 18], "操作をSQLiteの入力と対応させなさい。", [["queries.sql内のSQLを間接実行", ".read queries.sql"], ["以降の結果をresult.csvに書く", ".output result.csv"], ["画面出力へ戻す", ".output"]], [".quit"], ".readは入力するSQLファイルの読込み、.outputは実行結果の出力先変更です。");
  single(4, "SQL構築の考え方", [27, 28, 29, 30], "問い合わせを組み立てる際に資料で繰り返し示された考え方を選びなさい。", "使う表と結合経路、選択条件、出力内容を順に整理してからSQLにする", ["列名の綴りだけを先に覚え、表の関連は無視する", "表示したい表を必ず新規作成してから検索する", "SELECT句に必要な表名を全て並べる"], "SQLの記述順そのものと、設計時に考える順番を区別します。設計では必要なデータと関連を先に確認します。");
  sql(4, "単表の検索", [22, 24], "staff", ["departments"], "SELECT name FROM departments WHERE floor=1 ORDER BY id;", "書籍・食品", ["家具・玩具", "書籍だけ", "玩具・食品"], "floorが1なのはid10とid40です。SELECT nameなので名前だけを出力します。", "column");
  sql(4, "生年の検索", [26, 30], "staff", ["employees"], "SELECT name FROM employees WHERE birth_year=1988 ORDER BY id;", "山田・山本", ["山田だけ", "山本だけ", "佐藤・田中"], "1988年生まれはid1とid6です。入社年start_yearではなくbirth_yearで絞ります。", "column");
  sql(4, "年代の範囲条件", [31, 32, 34], "staff", ["employees"], "SELECT name FROM employees WHERE 2010<=start_year AND start_year<2020 ORDER BY id;", "山田・高橋・山本", ["山田・鈴木・高橋・山本", "佐藤・田中", "高橋だけ"], "2010年代は2010以上2020未満です。境界の2010は含み、2020は含めません。", "column");
  single(4, "SQLの意味を説明", [35, 43], "SELECT d.name,m.name FROM departments d JOIN employees m ON d.manager_id=m.id WHERE d.store_id=5; が何を検索するか選びなさい。", "店舗5の売場名と、その売場のマネージャ本人の名前", ["店舗5の全商品の名前と価格", "全社員とその部下の名前", "給与が5以上のマネージャ名"], "d.store_idは店舗ID、d.manager_id=m.idは売場の責任者本人を結ぶ条件です。");
  sql(4, "2表結合の実行結果", [38, 43], "staff", ["departments", "employees"], "SELECT m.name FROM departments d JOIN employees m ON d.manager_id=m.id WHERE d.store_id=5 ORDER BY d.id;", "山田・山本", ["山田・佐藤・山本", "鈴木・高橋", "山本だけ"], "店舗5の売場は書籍と玩具で、そのmanager_idは1と6です。社員のidで本人を引きます。", "column");
  sql(4, "結合後の選択", [44, 48], "staff", ["departments", "employees"], "SELECT d.name FROM departments d JOIN employees m ON d.manager_id=m.id WHERE m.salary>=15000 ORDER BY d.id;", "家具・玩具", ["書籍・食品", "家具だけ", "玩具だけ"], "責任者の給与が15000以上なのは鈴木の家具と山本の玩具です。条件は売場でなく社員mのsalaryへ指定します。", "column");
  sql(4, "部下を選ぶ結合", [35], "staff", ["departments", "employees"], "SELECT e.name FROM departments d JOIN employees e ON d.manager_id=e.manager_id WHERE d.id=10 ORDER BY e.id;", "山田・佐藤・山本", ["山田だけ", "鈴木・田中・高橋", "佐藤だけ"], "d.id=10の責任者IDは1です。manager_id=1の社員を拾うため、本人だけでなく同じ上司番号を持つ行も結果になります。", "column");
  sql(4, "自己結合と比較", [35, 36], "staff", ["employees"], "SELECT e.name FROM employees m JOIN employees e ON m.id=e.manager_id WHERE m.salary<e.salary ORDER BY e.id;", "山本", ["山田", "鈴木・高橋", "全社員"], "山本の給与20000が上司の山田12000を上回ります。mを上司、eを部下として比較します。資料のsalalyという誤植はsalaryへ直して使います。", "column");
  sql(4, "3表の経路", [49, 50, 53], "staff", ["items", "departments", "stores"], "SELECT i.name FROM items i JOIN departments d ON i.department_id=d.id JOIN stores s ON d.store_id=s.id WHERE i.price>=20000 AND s.id=7 ORDER BY i.id;", "机・棚", ["本・机", "机だけ", "棚だけ"], "商品から売場、売場から店舗へたどります。新宿店の家具売場にある机25000と棚20000が該当します。", "column");
  sql(4, "価格の境界", [54], "staff", ["items"], "SELECT name FROM items WHERE price<=3000 ORDER BY id;", "本・ボール・菓子", ["本・菓子", "ボールだけ", "机・棚"], "3000円以下なので3000円のボールも含みます。未満と以下の違いを確認します。", "column");
  sql(4, "仕入先経由の選択", [36, 55], "staff", ["suppliers", "items"], "SELECT i.name FROM suppliers r JOIN items i ON r.id=i.supplier_id WHERE r.address LIKE '%千代田区%' ORDER BY i.id;", "本・ボール・菓子", ["机・棚", "本だけ", "菓子だけ"], "千代田区の仕入先はid1と3で、それらが供給する商品をsupplier_idから選びます。", "column");
  sql(4, "在庫と結合", [55], "staff", ["items", "departments"], "SELECT d.name FROM items i JOIN departments d ON i.department_id=d.id WHERE i.qoh<50 ORDER BY i.id;", "家具・家具", ["家具だけ", "書籍・家具", "玩具・食品"], "机と棚がどちらも家具売場なので、DISTINCTを付けない検索結果では家具が2行現れます。", "column");
  free(4, "SQLを記述する", [26, 30, 34], "employees(id,name,birth_year,start_year)から、2010年代に入社した社員の名前を出すSQLを書きなさい。順序指定は不要。", "SELECT name FROM employees WHERE start_year>=2010 AND start_year<2020;", "同じ意味のSQLは複数あります。2010を含め2020を除くこと、出力列がnameであることを確認します。");
  free(4, "結合SQLを記述する", [38, 43], "departments(id,name,store_id,manager_id)とemployees(id,name)を使い、店舗5の売場名とマネージャ本人の名前を出すSQLを書きなさい。", "SELECT d.name,m.name FROM departments d JOIN employees m ON d.manager_id=m.id WHERE d.store_id=5;", "売場のmanager_idから社員のidへ結びます。e.manager_idと結ぶと部下を含む別の意味になるので注意します。");
  free(4, "SQLの修正と理由", [25, 35, 36], "『売場のマネージャ本人』の名前を出したいのに、ON d.manager_id=e.manager_id と書いてしまった。適切な条件と、修正が必要な理由を説明しなさい。", "ON d.manager_id=e.id とする。e.manager_idは社員の上司番号なので元の条件では売場の責任者を上司に持つ社員を選ぶ。本人のレコードは社員番号idで参照する。", "キーの名前を暗記するだけでなく、参照先と対象の人物を考えて修正する問題です。");

  single(3, "人工キーの定義", [53], "資料で示されたSQLiteの整数型人工主キーの定義例を選びなさい。", "id INTEGER PRIMARY KEY AUTOINCREMENT", ["id INTEGER FOREIGN KEY AUTONUMBER", "id TEXT ORDER BY ASC", "id SERIAL AUTO_INCREMENT KEY"], "資料ではDBMSによって記法が異なる点も説明されています。ここではSQLiteの例を問います。");

  single(5, "関係代数の閉包性", [16, 18], "関係代数が閉包性を持つとは、この講義では何を意味するか。", "関係を入力とする演算の結果が再び関係となり、別の演算の入力にできる", ["演算結果が必ず整数になる", "一度演算した関係は二度と使えない", "全ての演算はSQLのUPDATEである"], "選択した結果を射影し、その結果をさらに結合するなど、演算を組み合わせられます。");
  match(5, "関係代数の演算子", [18, 19, 31, 32, 40, 45], "関係代数の記号を演算名と対応させなさい。", [["∪", "和"], ["−", "差"], ["∩", "共通"], ["×", "直積"], ["σ", "選択"], ["π", "射影"], ["⋈", "結合"], ["÷", "商"]], [], "和と結合、共通と直積、行を取る選択と列を取る射影を区別します。");
  single(5, "和両立", [19], "和・差・共通を求める2関係に必要な和両立の条件を選びなさい。", "次数が等しく、対応する属性の型・定義域の並びが一致する", ["行数が等しければよい", "関係名が同じでなければならない", "主キー値が完全に同じでなければならない"], "行数や属性名の見た目ではなく、対応する値を同じ種類の組として扱えるかを確認します。直積には和両立は不要です。");
  sql(5, "和集合の計算", [19, 20], "sets", ["r", "s"], "SELECT a,b FROM r UNION SELECT c,d FROM s;", "5行", ["1行", "6行", "9行"], "和には(a,1),(a,2),(a,3),(b,1),(b,2)の5組があり、共通の(a,1)は重複して数えません。", "rowCount");
  sql(5, "共通集合の計算", [19, 24], "sets", ["r", "s"], "SELECT a,b FROM r INTERSECT SELECT c,d FROM s;", "1行", ["0行", "3行", "5行"], "両方に含まれるタプルは(a,1)だけです。", "rowCount");
  sql(5, "差集合の計算", [19, 22], "sets", ["r", "s"], "SELECT a,b FROM r EXCEPT SELECT c,d FROM s;", "2行", ["0行", "1行", "3行"], "rにあってsにない組は(a,2),(b,1)の2つです。", "rowCount");
  single(5, "差の向き", [22, 23], "一般にR−SとS−Rは等しいか。", "一般には等しくない", ["必ず等しい", "どちらも必ず空集合になる", "どちらも必ずR∪Sと等しい"], "引く側と引かれる側を入れ替えると、残るタプルが変わります。差は一般には交換できません。");
  match(5, "直積の行数と次数", [26, 27], "Rが3行2列、Sが4行3列のとき、R×Sのタプル数と次数を対応させなさい。", [["タプル数", "12"], ["次数", "5"]], ["7", "6"], "全組合せなので行数は3×4=12、両表の属性を連結するので次数は2+3=5です。");
  match(5, "単項・二項演算", [28], "演算を必要とする関係の個数に対応させなさい。", [["選択", "1つ"], ["射影", "1つ"], ["結合", "2つ"], ["商", "2つ"]], [], "選択と射影は単項演算、結合と商は二項演算です。");
  match(5, "SQLと関係代数", [29, 30, 31, 32], "SQLの各部分を対応する関係代数の操作と対応させなさい。", [["WHEREで条件に合う行を取る", "選択"], ["SELECT DISTINCTで必要な列の組を取る", "射影"], ["JOIN ... ON ...で関連する行を連結する", "結合"]], [], "SQLのSELECTという単語そのものと、関係代数のselectionは同じ役割ではありません。行の選択はWHEREに対応します。");
  sql(5, "選択の計算", [31, 34], "projection", ["r"], "SELECT id FROM r WHERE x=2 ORDER BY id;", "C・D・E", ["A・B", "D・E・F", "Cだけ"], "x=2を満たす行はC,D,Eです。射影前の段階では元の行を条件で絞ります。", "column");
  sql(5, "射影と重複除去", [32, 34], "projection", ["r"], "SELECT DISTINCT x FROM r WHERE id<'E' ORDER BY x;", "1・2", ["1・1・2・2", "1・2・3", "2だけ"], "idがEより前のA〜Dを選び、xだけを取り重複を除くと1と2になります。", "column");
  sql(5, "射影と行数", [32, 35], "projection", ["r"], "SELECT DISTINCT y FROM r WHERE id>'E' ORDER BY id;", "大阪・京都", ["東京・大阪", "大阪だけ", "東京・大阪・京都"], "該当するFとGのyは大阪と京都です。行の選択をした後、列yへ射影します。", "column");
  single(5, "射影による件数変化", [32], "7行3列の関係を1列に射影した結果、その列の異なる値が3つだった。結果の行数を答えなさい。", "3行", ["7行", "1行", "21行"], "関係代数の射影では同じ値の組を重複させないので3行になります。単なるSQLのSELECT列名だけとは区別します。");
  single(5, "結合の成り立ち", [39, 40], "条件θによる結合R⋈θSを表すものを選びなさい。", "R×Sからθを満たすタプルを選択した関係", ["RとSの共通タプルだけを取った関係", "R−Sを計算した関係", "RとSの平均値を取った数値"], "結合は直積と選択の組合せとして説明できます。実際のDBMSは必ず直積をすべて実体化するとは限りません。");
  sql(5, "等結合の行数", [41], "joins", ["r", "s"], "SELECT * FROM r JOIN s ON r.a=s.c;", "5行", ["1行", "3行", "12行"], "rのaがaの2行はsのaの1行と対応して2行、rのbの1行はsのbの3行と対応して3行、合計5行です。", "rowCount");
  sql(5, "別の属性で結合", [41], "joins", ["r", "s"], "SELECT * FROM r JOIN s ON r.b=s.d;", "1行", ["0行", "3行", "5行"], "bとdが一致するのは2だけなので、rの(a,2)とsの(a,2)の組1行です。", "rowCount");
  sql(5, "結合による行の増加", [41], "joins", ["s", "t"], "SELECT * FROM s JOIN t ON s.c=t.e;", "6行", ["2行", "3行", "4行"], "sのc=bの3行とtのe=bの2行が全て組み合わさるため3×2=6行です。", "rowCount");
  match(5, "結合の利用パターン", [42, 43, 44], "講義の利用パターンと説明を対応させなさい。", [["全合成", "両方の関係の情報を組み合わせる"], ["補足", "主役の関係へ他の関係の属性を付加する"], ["間接選択", "他の関係へ与えた条件を使って主役の行を選ぶ"]], [], "同じJOINでも、何を出力しどこへ条件を付けるかで問い合わせの役割が変わります。");
  single(5, "商の意味", [45], "履修(学生,科目)を、必要科目の関係で割った商はどのような学生を表すか。", "必要科目の全てを履修している学生", ["必要科目のうち少なくとも1つだけを履修している学生", "必要科目を1つも履修していない学生", "履修件数が平均より多い学生"], "商は『全ての相手と組になっている』という条件を表します。少なくとも1つという条件とは異なります。");
  sql(5, "商の具体的計算", [45], "division", ["enrolments"], "SELECT student FROM enrolments WHERE course IN ('数学','英語') GROUP BY student HAVING COUNT(DISTINCT course)=2 ORDER BY student;", "A・C", ["A・B・C", "Aだけ", "Bだけ"], "数学と英語の両方を履修しているのはAとCです。追加で体育や国語を履修していても条件を満たします。", "column");
