  match(5, "集約関数の意味", [51], "SQLの集約関数を役割と対応させなさい。", [["COUNT", "件数"], ["SUM", "合計"], ["AVG", "平均"], ["MAX", "最大値"], ["MIN", "最小値"]], [], "複数行の値を一つの集約値にまとめます。GROUP BYを付けるとグループごとに求めます。");
  sql(5, "COUNTの違い", [52], "nulls", ["emp"], "SELECT COUNT(*) FROM emp;", "4", ["2", "3", "6"], "COUNT(*)は列のNULLに関係なく全行を数えるので4です。");
